-- create "rte_source_offsets" table
CREATE TABLE "rte_source_offsets" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "deleted_at" timestamptz NULL,
  "topic" character varying NOT NULL,
  "partition" integer NOT NULL,
  "last_offset" bigint NOT NULL,
  PRIMARY KEY ("id")
);
-- create index "rtesourceoffset_topic_partition" to table: "rte_source_offsets"
CREATE UNIQUE INDEX "rtesourceoffset_topic_partition" ON "rte_source_offsets" ("topic", "partition");
-- drop "rte_invalidations" table
DROP TABLE "rte_invalidations";
